class Solution {
public:
    bool sumGame(string num) {
        int n = num.size();
        int half = n / 2;
        int sumDiff = 0, qDiff = 0;
        for (int i = 0; i < half; i++) {
            if (num[i] == '?') qDiff++;
            else sumDiff += num[i] - '0';
        }
        for (int i = half; i < n; i++) {
            if (num[i] == '?') qDiff--;
            else sumDiff -= num[i] - '0';
        }
        if (qDiff % 2 != 0) return true;
        return sumDiff * 2 != -qDiff * 9;
    }
};

class Solution {
    public boolean sumGame(String num) {
        int n = num.length();
        int half = n / 2;
        int sumDiff = 0, qDiff = 0;
        for (int i = 0; i < half; i++) {
            if (num.charAt(i) == '?') qDiff++;
            else sumDiff += num.charAt(i) - '0';
        }
        for (int i = half; i < n; i++) {
            if (num.charAt(i) == '?') qDiff--;
            else sumDiff -= num.charAt(i) - '0';
        }
        if (qDiff % 2 != 0) return true;
        return sumDiff * 2 != -qDiff * 9;
    }
}

